<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Skill; use Illuminate\Http\Request;
class SkillController extends Controller { public function index(){return view('admin.skills.index',['items'=>Skill::orderBy('sort_order')->get()]);} public function create(){return view('admin.skills.form',['item'=>new Skill]);} public function store(Request $r){Skill::create($this->data($r));return redirect()->route('admin.skills.index')->with('success','Keahlian ditambahkan.');} public function edit(Skill $skill){return view('admin.skills.form',['item'=>$skill]);} public function update(Request $r,Skill $skill){$skill->update($this->data($r));return redirect()->route('admin.skills.index')->with('success','Keahlian diperbarui.');} public function destroy(Skill $skill){$skill->delete();return back()->with('success','Keahlian dihapus.');} private function data(Request $r):array{return $r->validate(['name'=>'required|string|max:100','category'=>'nullable|string|max:100','level'=>'nullable|integer|min:1|max:100','sort_order'=>'nullable|integer|min:0']);} }
